def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(1, h - 1):
        if all(v == 0 for v in grid[r]) and any(v != 0 for v in grid[r - 1]) and any(v != 0 for v in grid[r + 1]):
            out[r] = [3] * w
            break
    return out
